import sys
import heapq

def dijkstra(graph, start, n):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        current_dist, u = heapq.heappop(pq)
        if current_dist > dist[u]:
            continue
        for v, weight in graph[u]:
            distance = current_dist + weight
            if distance < dist[v]:
                dist[v] = distance
                heapq.heappush(pq, (distance, v))
    return dist

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    m = int(data[index + 1])
    k = int(data[index + 2])
    index += 3

    flights = []
    for _ in range(m):
        d_i = int(data[index])
        f_i = int(data[index + 1])
        t_i = int(data[index + 2])
        c_i = int(data[index + 3])
        index += 4
        flights.append((d_i, f_i, t_i, c_i))

    # Create graphs for forward and backward flights
    forward_graph = [[] for _ in range(n + 1)]
    backward_graph = [[] for _ in range(n + 1)]

    for d_i, f_i, t_i, c_i in flights:
        if f_i == 0:
            backward_graph[t_i].append((0, c_i))
        elif t_i == 0:
            forward_graph[f_i].append((0, c_i))
        else:
            forward_graph[f_i].append((t_i, c_i))
            backward_graph[t_i].append((f_i, c_i))

    # Calculate shortest paths to Metropolis
    forward_dist = dijkstra(forward_graph, 0, n)
    backward_dist = dijkstra(backward_graph, 0, n)

    min_cost = float('inf')
    for d_i, f_i, t_i, c_i in flights:
        if f_i == 0:
            if d_i + k + backward_dist[t_i] <= 10**6:
